// Browser-side helpers for the LLM-friendly documentation generated by sphinx-llm.
(function () {
  // URL of the Markdown twin of the current page, or null for unknown URL formats.
  function markdownUrl() {
    var pathname = window.location.pathname;
    if (pathname.endsWith(".html")) {
      // Standard HTML builder: api.html -> api.html.md
      return pathname.replace(/\.html$/, ".html.md");
    }
    if (pathname.endsWith("/")) {
      // dirhtml builder: api/ -> api/index.html.md
      return pathname + "index.html.md";
    }
    return null;
  }

  // Adds a "Download Markdown" link next to "Edit on GitHub" and "Show Source"
  // in the secondary sidebar of the pydata theme.
  function addMarkdownLink() {
    var url = markdownUrl();
    var sourceLink = document.querySelector(".bd-sidebar-secondary .sourcelink");
    if (!url || !sourceLink) {
      return;
    }

    var section = document.createElement("div");
    section.className = "tocsection markdownlink";
    var a = document.createElement("a");
    a.href = url;
    a.setAttribute("download", "");
    a.setAttribute("title", "Download this page as Markdown (LLM-friendly)");
    var icon = document.createElement("i");
    icon.className = "fa-brands fa-markdown";
    a.appendChild(icon);
    a.appendChild(document.createTextNode(" Download Markdown"));
    section.appendChild(a);

    sourceLink.parentNode.insertBefore(section, sourceLink.nextSibling);
  }

  // Buttons with a `data-copy-url` attribute copy the absolute URL of the
  // referenced file, resolved against the current page, so the copied URL always
  // belongs to the documentation version being read.
  function setUpCopyButtons() {
    document.querySelectorAll("[data-copy-url]").forEach(function (button) {
      var label = button.querySelector(".llm-button-label");
      var original = label ? label.textContent : "";
      button.addEventListener("click", function () {
        var url = new URL(button.getAttribute("data-copy-url"), window.location.href).href;
        navigator.clipboard.writeText(url).then(
          function () {
            if (label) {
              label.textContent = "Copied!";
              setTimeout(function () {
                label.textContent = original;
              }, 2000);
            }
          },
          function () {
            window.prompt("Copy the URL:", url);
          }
        );
      });
    });
  }

  document.addEventListener("DOMContentLoaded", function () {
    addMarkdownLink();
    setUpCopyButtons();
  });
})();
